preConditionHook:
// Entry & Exit Confessions E26 "Classic Keltner Channel", verbatim --
// deliberately NOT split: the band cross AND the length2-bar momentum
// confirmation, as the book's code has them (its plain-English text
// omits the momentum term). Equals KeltnerChannelCross + Momentum(length2).
// EEC E26's bands: Average(close, length) -/+ numAtrs x ATR. EL's Average
// recomputes from scratch every bar, newest-first (bar [0] added first).
kcAvg = 0.0;
for (int i = 0; i < (int)length; ++i) {
    kcAvg += close[i];
}
kcAvg /= (int)length;
// The book prints plain AvgTrueRange, but MultiWalk overrides the series
// functions its strategies use, so the twin calls WFSafe_AvgTrueRange -- a
// ROLLING accumulator, not a fresh mean (AtrProfitTarget is the reference):
// seeded with a full length-term sum on the study's first calculated bar,
// re-seeded when the length changes; from there S += in; S -= out; -- TWO
// statements, because EL evaluates S[1] + Price - Price[Length] left to
// right and folding to S += in - out rounds differently. The twin calls it
// at one length from two call sites; both sites carry identical state, so
// one accumulator serves both bands.
if (atrLength != (int)length) {
    atrSum = 0.0;
    for (int i = 0; i < (int)length; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)length;
} else {
    const int out = (int)length;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
kcAtr = atrSum / (int)length;
lowerBand = kcAvg - numAtrs * kcAtr;
upperBand = kcAvg + numAtrs * kcAtr;
// EL's `crosses` is a STATE MACHINE, not a two-bar test (the `crosses over` /
// `crosses under` register row, VERIFIED): it fires when the toleranced
// comparison holds AND the most recent NON-equal bar was on the other side.
// An equality run (el_eq, absolute 2.22e-12) is BRIDGED -- above -> equal ->
// above does NOT re-fire -- and the side starts UNKNOWN (0) at the first
// evaluated bar, so nothing can fire on bar 1. The book assigns the bands to
// EL variables, but they are recomputed from price every bar, so the cross
// state is modelled on the computed band values.
crossUpLower = el_gt(close[0], lowerBand) && lastSideLower == -1;
crossDownUpper = el_lt(close[0], upperBand) && lastSideUpper == 1;
// Update the sides AFTER the fire flags; an el_eq bar leaves them unchanged.
if (el_gt(close[0], lowerBand)) { lastSideLower = 1; }
else if (el_lt(close[0], lowerBand)) { lastSideLower = -1; }
if (el_gt(close[0], upperBand)) { lastSideUpper = 1; }
else if (el_lt(close[0], upperBand)) { lastSideUpper = -1; }
